function LiveEvents() {
  const client = useQueryClient(); const { isSignedIn } = useUser();
  useEffect(() => {
    if (!isSignedIn) return;
    let source: EventSource | null = null; let retryTimer: number | undefined; let closed = false;
    const refresh = () => {
      [getGetMeQueryKey(),getGetDashboardQueryKey(),getListConversationsQueryKey(),getGetVerificationQueryKey(),getListVerificationRequestsQueryKey()].forEach(queryKey => void client.invalidateQueries({queryKey}));
      void client.invalidateQueries({queryKey:getListMessagesQueryKey()}); void client.invalidateQueries({queryKey:getListPeopleQueryKey()});
    };
    const connect = () => {
      if (closed) return; source = new EventSource('/api/events');
      source.onmessage = event => {
        refresh();
        try {
          const payload = JSON.parse(event.data) as {type?:string;conversationId?:string;userId?:string;isTyping?:boolean};
          if (payload.type === 'typing') window.dispatchEvent(new CustomEvent('first-commit:typing', {detail:payload}));
        } catch { /* Keepalive events still refresh the live workspace. */ }
      }; source.onopen = refresh;
      source.onerror = () => { source?.close(); if (!closed) retryTimer = window.setTimeout(connect, 2500); };
    };
    connect(); return () => { closed = true; source?.close(); window.clearTimeout(retryTimer); };
  }, [client,isSignedIn]);
  return null;
}
