function ProtectedShell({ children }: { children: ReactNode }) { return <RequireAuth><AuthenticatedLayout>{children}</AuthenticatedLayout></RequireAuth>; }

function useRefreshProductQueries() {
  const client=useQueryClient();
  return () => {
    void client.invalidateQueries({queryKey:getGetMeQueryKey()});void client.invalidateQueries({queryKey:getGetDashboardQueryKey()});
    void client.invalidateQueries({queryKey:getListConversationsQueryKey()});void client.invalidateQueries({queryKey:getListMessagesQueryKey()});
    void client.invalidateQueries({queryKey:getGetVerificationQueryKey()});void client.invalidateQueries({queryKey:getListVerificationRequestsQueryKey()});
  };
}
function ChatHub() {
  const {data:me}=useGetMe(); const {data:dashboard,isLoading:loadingDashboard,isError:dashboardError,refetch:retryDashboard}=useGetDashboard();
  const {data:conversations,isLoading,isError,refetch}=useListConversations(); const [,setLocation]=useLocation();
  const [activeId,setActiveId]=useState(()=>new URLSearchParams(window.location.search).get('conversation')||'');
  const [filter,setFilter]=useState(''); const list=conversations||[];
  const active=useMemo(()=>list.find(c=>c.id===activeId)||null,[list,activeId]);
  const visible=list.filter(c=>`${c.peer.displayName} ${c.lastMessage?.content||''}`.toLowerCase().includes(filter.toLowerCase()));
  return <div className="animate-rise">
    <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="mb-2 text-[11px] font-bold uppercase tracking-[.18em] text-primary">Your campus, closer</p><h1 className="font-serif text-[34px] font-extrabold tracking-[-.055em] sm:text-[42px]">Good to see you, {me?.displayName?.split(' ')[0]||'there'}.</h1><p className="mt-2 text-sm text-muted-foreground">Pick up a conversation or meet someone new.</p></div><Link href="/people" className="inline-flex items-center justify-center gap-2 rounded-full bg-primary px-5 py-3 text-sm font-bold text-white shadow-sm transition hover:-translate-y-0.5 hover:bg-[#205843]" data-testid="link-find-people"><Plus size={17}/> Find someone</Link></div>
    <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">{[
      {label:'Conversations',value:dashboard?.conversationCount??'—',icon:MessageCircle,tone:'bg-[#e6efe7] text-primary'},
      {label:'Unread messages',value:dashboard?.unreadCount??'—',icon:Mail,tone:'bg-[#f4e8d7] text-[#9a7048]'},
      {label:'Verified students',value:dashboard?.verifiedCampusMembers??'—',icon:BadgeCheck,tone:'bg-[#e8ebf0] text-[#617b93]'},
      {label:'Around right now',value:dashboard?.onlineMembers??'—',icon:Users,tone:'bg-[#f0e8e8] text-[#9c6664]'},
    ].map((item,i)=>{const Icon=item.icon;return <div key={item.label} className={`animate-rise rounded-2xl border border-[#e7e3d9] bg-[#fffdf8] p-4 sm:p-5 ${i>0?`delay-${i}`:''}`} data-testid={`stat-${item.label.toLowerCase().replaceAll(' ','-')}`}><div className="flex items-center justify-between"><span className="text-[11px] font-semibold text-muted-foreground">{item.label}</span><span className={`grid h-8 w-8 place-items-center rounded-xl ${item.tone}`}><Icon size={15}/></span></div><p className="mt-3 font-serif text-2xl font-extrabold tracking-tight">{loadingDashboard?'…':item.value}</p></div>})}</div>
    {dashboardError&&<div className="mb-4"><ErrorNotice retry={()=>void retryDashboard()}/></div>}
    <div className="grid min-h-[570px] overflow-hidden rounded-[26px] border border-[#e4e0d7] bg-[#fffdf8] shadow-[0_12px_40px_rgba(39,53,46,.055)] lg:grid-cols-[350px_1fr]">
      <section className={`${active?'hidden lg:block':''} border-r border-[#ece8df]`}>
        <div className="border-b border-[#ece8df] px-5 pb-4 pt-5"><div className="flex items-center justify-between"><div><h2 className="font-serif text-xl font-extrabold tracking-tight">Messages</h2><p className="mt-1 text-xs text-muted-foreground">{list.length} private conversations</p></div><button className="grid h-9 w-9 place-items-center rounded-xl bg-[#edf3ed] text-primary transition hover:bg-[#dceade]" onClick={()=>setLocation('/people')} aria-label="Start a conversation" data-testid="button-new-conversation"><Plus size={18}/></button></div><label className="mt-4 flex items-center gap-2 rounded-xl bg-[#f4f2eb] px-3.5"><Search size={16} className="text-[#88918b]"/><input value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Find a conversation" className="h-10 w-full bg-transparent text-xs outline-none placeholder:text-[#929b94]" data-testid="input-filter-conversations"/></label></div>
        <div className="max-h-[490px] overflow-auto p-2">{isLoading?<LoadingRows/>:isError?<ErrorNotice retry={()=>void refetch()}/>:visible.length?visible.map(c=><ConversationRow key={c.id} conversation={c} selected={c.id===activeId} onClick={()=>setActiveId(c.id)}/>):<div className="px-5 py-12 text-center"><span className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-[#edf3ed] text-primary"><MessageCircle size={21}/></span><p className="mt-4 text-sm font-bold">{filter?'No matches':'A clean slate'}</p><p className="mx-auto mt-1 max-w-[210px] text-xs leading-5 text-muted-foreground">{filter?'Try a different name or message.':'Start by finding someone from your campus.'}</p>{!filter&&<Link href="/people" className="mt-4 inline-block text-xs font-bold text-primary" data-testid="link-empty-find-people">Find people <ArrowRight size={13} className="ml-1 inline"/></Link>}</div>}</div>
      </section>
      <section className={`${active?'':'hidden lg:flex'} min-w-0 flex-col`}>
        {active?<ConversationPane conversation={active} currentUser={me} onBack={()=>setActiveId('')}/>:<div className="relative flex min-h-[560px] flex-1 items-center justify-center overflow-hidden p-8 text-center"><div className="absolute right-12 top-10 h-32 w-32 rounded-full bg-[#edf2e8]"/><div className="absolute bottom-10 left-8 h-28 w-28 rounded-full bg-[#f4eadc]"/><div className="relative max-w-[370px]"><span className="mx-auto grid h-[74px] w-[74px] place-items-center rounded-[26px] bg-[#e9f0e8] text-primary"><MessageCircle size={31}/></span><p className="mt-6 text-[11px] font-bold uppercase tracking-[.19em] text-primary">A little more human</p><h2 className="mt-3 font-serif text-3xl font-extrabold tracking-[-.05em]">Every good thing starts somewhere.</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">Your private conversations live here. Find someone who shares your campus, your classes, or your curiosity.</p><Link href="/people" className="mt-6 inline-flex items-center gap-2 rounded-full bg-primary px-5 py-3 text-sm font-bold text-white transition hover:bg-[#205843]" data-testid="link-empty-start">Meet someone new <ArrowRight size={15}/></Link></div></div>}
      </section>
    </div>
  </div>;
}
function ConversationRow({conversation,selected,onClick}:{conversation:Conversation;selected:boolean;onClick:()=>void}) {
  const time=conversation.updatedAt?new Date(conversation.updatedAt).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'}):'';
  return <button onClick={onClick} className={`flex w-full items-center gap-3 rounded-2xl p-3 text-left transition ${selected?'bg-[#edf3ed]':'hover:bg-[#f7f5ef]'}`} data-testid={`conversation-${conversation.id}`}><PersonAvatar person={conversation.peer}/><span className="min-w-0 flex-1"><span className="flex items-center justify-between gap-2"><span className="flex min-w-0 items-center gap-1.5 truncate text-sm font-bold">{conversation.peer.displayName}{conversation.peer.verificationStatus==='verified'&&<BadgeCheck size={13} className="shrink-0 text-primary"/>}</span><span className="shrink-0 text-[10px] text-muted-foreground">{time}</span></span><span className="mt-1 flex items-center justify-between gap-2"><span className="truncate text-xs text-muted-foreground">{conversation.lastMessage?.isDeleted?'Message removed':conversation.lastMessage?.content||'Say hello to start'}</span>{conversation.unreadCount>0&&<span className="grid h-5 min-w-5 place-items-center rounded-full bg-primary px-1 text-[10px] font-bold text-white">{conversation.unreadCount}</span>}</span></span></button>;
}
function ConversationPane({conversation,currentUser,onBack}:{conversation:Conversation;currentUser?:User;onBack:()=>void}) {
  const params={conversationId:conversation.id,limit:100};const {data:messages,isLoading,isError,refetch}=useListMessages(params,{query:{enabled:!!conversation.id,queryKey:getListMessagesQueryKey(params)}});
  const send=useSendMessage();const markRead=useMarkConversationRead();const typing=useSetTypingStatus();const edit=useEditMessage();const remove=useDeleteMessage();const addReaction=useAddReaction();const removeReaction=useRemoveReaction();const refresh=useRefreshProductQueries();
  const [draft,setDraft]=useState('');const [replyTo,setReplyTo]=useState<string|null>(null);const [editing,setEditing]=useState<string|null>(null);const [editValue,setEditValue]=useState('');const [typingPeer,setTypingPeer]=useState(false);const bottom=useRef<HTMLDivElement>(null);const typingTimeout=useRef<number|undefined>(undefined);
  useEffect(()=>{void markRead.mutateAsync({conversationId:conversation.id}).then(refresh).catch(()=>{});},[conversation.id]);
  useEffect(()=>{const onTyping=(event:Event)=>{const payload=(event as CustomEvent<{conversationId?:string;userId?:string;isTyping?:boolean}>).detail;if(payload.conversationId===conversation.id&&payload.userId!==currentUser?.id)setTypingPeer(!!payload.isTyping);};window.addEventListener('first-commit:typing',onTyping);return()=>window.removeEventListener('first-commit:typing',onTyping);},[conversation.id,currentUser?.id]);
  useEffect(()=>{bottom.current?.scrollIntoView({behavior:'smooth'});},[messages?.length]);
  useEffect(()=>()=>window.clearTimeout(typingTimeout.current),[]);
  function sendMessage(event:FormEvent) {event.preventDefault();const content=draft.trim();if(!content||send.isPending)return;send.mutate({conversationId:conversation.id,data:{content,replyToId:replyTo}},{onSuccess:()=>{setDraft('');setReplyTo(null);void refresh();void typing.mutate({conversationId:conversation.id,data:{isTyping:false}});}});}
  function changeDraft(value:string) {setDraft(value);if(!value)return;void typing.mutate({conversationId:conversation.id,data:{isTyping:true}});window.clearTimeout(typingTimeout.current);typingTimeout.current=window.setTimeout(()=>void typing.mutate({conversationId:conversation.id,data:{isTyping:false}}),1200);}
  function toggleReaction(message:Message) {const existing=message.reactions.find(r=>r.reactedByMe);if(existing)removeReaction.mutate({messageId:message.id,emoji:existing.emoji},{onSuccess:refresh});else addReaction.mutate({messageId:message.id,data:{emoji:'like'}},{onSuccess:refresh});}
  return <div className="flex h-full min-h-[570px] flex-col">
    <header className="flex h-[76px] shrink-0 items-center gap-3 border-b border-[#ece8df] px-4 sm:px-6"><button onClick={onBack} className="grid h-9 w-9 place-items-center rounded-xl text-muted-foreground hover:bg-muted lg:hidden" aria-label="Back to conversations" data-testid="button-back-conversations"><ArrowLeft size={18}/></button><PersonAvatar person={conversation.peer}/><div className="min-w-0 flex-1"><div className="flex items-center gap-1.5"><h2 className="truncate text-sm font-extrabold">{conversation.peer.displayName}</h2>{conversation.peer.verificationStatus==='verified'&&<BadgeCheck size={14} className="text-primary"/>}</div><p className="mt-0.5 text-[11px] text-muted-foreground">{conversation.peer.isOnline?'Online now':conversation.peer.program||conversation.peer.university||'Campus member'}</p></div><button className="grid h-9 w-9 place-items-center rounded-xl text-muted-foreground hover:bg-muted" aria-label="More conversation options" onClick={()=>setReplyTo(null)} data-testid="button-conversation-more"><MoreHorizontal size={19}/></button></header>
    <div className="flex items-center justify-center gap-2 border-b border-[#f0ede6] bg-[#f8f7f2] px-4 py-2.5 text-[10px] font-medium text-muted-foreground"><LockKeyhole size={12}/> Your conversation with {conversation.peer.displayName.split(' ')[0]} is private.</div>
    <div className="flex-1 space-y-4 overflow-auto bg-[radial-gradient(ellipse_at_top,_#f8f7f1_0%,_#fffdf8_54%)] px-4 py-6 sm:px-7">{isLoading?<LoadingRows/>:isError?<ErrorNotice retry={()=>void refetch()}/>:messages?.length?messages.map(message=><MessageBubble key={message.id} message={message} own={message.senderId===currentUser?.id} editing={editing===message.id} editValue={editValue} onEditValue={setEditValue} onStartEdit={()=>{setEditing(message.id);setEditValue(message.content);}} onSaveEdit={()=>edit.mutate({messageId:message.id,data:{content:editValue}},{onSuccess:()=>{setEditing(null);void refresh();}})} onCancelEdit={()=>setEditing(null)} onDelete={()=>{if(window.confirm('Remove this message from the conversation?'))remove.mutate({messageId:message.id},{onSuccess:refresh});}} onReply={()=>setReplyTo(message.id)} onReact={()=>toggleReaction(message)}/>):<div className="mx-auto max-w-[330px] py-16 text-center"><span className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-[#eaf1eb] text-primary"><MessageCircle size={21}/></span><p className="mt-4 text-sm font-bold">The first hello is yours.</p><p className="mt-1 text-xs leading-5 text-muted-foreground">You and {conversation.peer.displayName.split(' ')[0]} can take it from here.</p></div>}<div ref={bottom}/></div>
    {replyTo&&<div className="flex items-center justify-between border-t border-[#eeeae2] bg-[#f8f7f2] px-5 py-2 text-xs text-muted-foreground"><span>Replying to a message</span><button onClick={()=>setReplyTo(null)} aria-label="Cancel reply" data-testid="button-cancel-reply"><X size={15}/></button></div>}
    {typingPeer&&<p className="px-6 py-1 text-xs text-muted-foreground">{conversation.peer.displayName.split(' ')[0]} is writing…</p>}
    {send.isError&&<p className="px-5 py-2 text-xs font-medium text-destructive" role="alert">Your message didn’t send. Please try again.</p>}
    <form onSubmit={sendMessage} className="flex items-end gap-2 border-t border-[#ece8df] bg-[#fffdf8] p-3 sm:p-4"><Textarea value={draft} onChange={e=>changeDraft(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage(e);}}} placeholder={`Message ${conversation.peer.displayName.split(' ')[0]}…`} className="max-h-32 min-h-[46px] resize-none rounded-2xl border-0 bg-[#f3f1e9] px-4 py-3 text-sm shadow-none focus-visible:ring-1 focus-visible:ring-primary" data-testid="input-message-composer"/><Button type="submit" disabled={!draft.trim()||send.isPending} className="h-11 w-11 shrink-0 rounded-2xl p-0" aria-label="Send message" data-testid="button-send-message">{send.isPending?<span className="h-4 w-4 animate-pulse rounded-full bg-white"/>:<Send size={17}/>}</Button></form>
  </div>;
}
function MessageBubble({message,own,editing,editValue,onEditValue,onStartEdit,onSaveEdit,onCancelEdit,onDelete,onReply,onReact}:{message:Message;own:boolean;editing:boolean;editValue:string;onEditValue:(v:string)=>void;onStartEdit:()=>void;onSaveEdit:()=>void;onCancelEdit:()=>void;onDelete:()=>void;onReply:()=>void;onReact:()=>void}) {
  const stamp=new Date(message.createdAt).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'});
  return <div className={`group flex ${own?'justify-end':'justify-start'}`} data-testid={`message-${message.id}`}><div className={`max-w-[82%] sm:max-w-[70%] ${own?'items-end':'items-start'} flex flex-col`}><p className={`mb-1 px-1 text-[10px] font-bold ${own?'text-right text-[#75817a]':'text-[#75817a]'}`}>{own?'You':message.senderName} <span className="ml-1 font-normal">{stamp}{message.editedAt?' · edited':''}</span></p><div className={`relative rounded-[18px] px-4 py-3 text-sm leading-6 ${own?'rounded-br-md bg-[#2c7057] text-white':'rounded-bl-md border border-[#eee9df] bg-white text-ink shadow-[0_2px_8px_rgba(35,50,42,.035)]'}`}>
    {message.isDeleted?<span className="italic opacity-70">This message was removed.</span>:editing?<div className="min-w-[220px]"><Textarea value={editValue} onChange={e=>onEditValue(e.target.value)} className="min-h-20 bg-white text-ink" data-testid={`input-edit-message-${message.id}`}/><div className="mt-2 flex justify-end gap-2"><button onClick={onCancelEdit} className="text-xs">Cancel</button><button onClick={onSaveEdit} className="rounded-lg bg-primary px-2.5 py-1 text-xs font-bold text-white" data-testid={`button-save-edit-${message.id}`}>Save</button></div></div>:message.content}
    </div>{!message.isDeleted&&<div className={`mt-1 flex items-center gap-1 opacity-0 transition group-hover:opacity-100 focus-within:opacity-100 ${own?'justify-end':''}`}><button onClick={onReply} className="rounded-md px-2 py-1 text-[10px] font-semibold text-muted-foreground hover:bg-muted" data-testid={`button-reply-${message.id}`}>Reply</button>{own&&<><button onClick={onStartEdit} className="grid h-6 w-6 place-items-center rounded-md text-muted-foreground hover:bg-muted" aria-label="Edit message" data-testid={`button-edit-${message.id}`}><Pencil size={12}/></button><button onClick={onDelete} className="grid h-6 w-6 place-items-center rounded-md text-muted-foreground hover:bg-[#f8e9e7] hover:text-destructive" aria-label="Delete message" data-testid={`button-delete-${message.id}`}><X size={14}/></button></>}<button onClick={onReact} className="rounded-md px-2 py-1 text-[10px] font-semibold text-muted-foreground hover:bg-muted" data-testid={`button-reaction-${message.id}`}>{message.reactions.length?`Appreciate · ${message.reactions.reduce((sum,r)=>sum+r.count,0)}`:'Appreciate'}</button></div>}</div></div>;
}

function PeoplePage() {
  const [search,setSearch]=useState('');const params={search:search.trim()||undefined,includeDemo:true};const {data:people,isLoading,isError,refetch}=useListPeople(params,{query:{queryKey:getListPeopleQueryKey(params)}});
  const start=useStartConversation();const [,setLocation]=useLocation();const refresh=useRefreshProductQueries();const {data:me}=useGetMe();const [tab,setTab]=useState<'all'|'online'>('all');
  const filtered=(people||[]).filter(p=>p.id!==me?.id&&(tab==='all'||p.isOnline));
  function startChat(person:User){start.mutate({data:{peerUserId:person.id}},{onSuccess:conversation=>{void refresh();setLocation(`/app?conversation=${conversation.id}`);}});}
  return <div className="animate-rise"><PageTitle eyebrow="The people around you" title="Find your people." desc="Search the verified students at your university. Find a familiar classmate, or someone new to learn from." action={<div className="rounded-full border border-[#dce6dc] bg-[#edf3ed] px-3.5 py-2 text-xs font-bold text-primary"><ShieldCheck size={14} className="mr-1 inline"/> Verified students only</div>}/>
    <div className="mb-6 flex flex-col gap-3 sm:flex-row"><label className="flex h-12 flex-1 items-center gap-3 rounded-2xl border border-[#e2dfd6] bg-[#fffdf8] px-4 shadow-sm focus-within:border-primary"><Search size={18} className="text-[#87918b]"/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search by name, program, or campus" className="w-full bg-transparent text-sm outline-none placeholder:text-[#9aa19b]" data-testid="input-search-people"/></label><div className="flex rounded-2xl border border-[#e2dfd6] bg-[#fffdf8] p-1"><button onClick={()=>setTab('all')} className={`rounded-xl px-4 text-xs font-bold ${tab==='all'?'bg-[#e9f1e9] text-primary':'text-muted-foreground'}`} data-testid="button-filter-all">Everyone</button><button onClick={()=>setTab('online')} className={`rounded-xl px-4 text-xs font-bold ${tab==='online'?'bg-[#e9f1e9] text-primary':'text-muted-foreground'}`} data-testid="button-filter-online">Online now</button></div></div>
    <div className="mb-4 flex items-center justify-between"><p className="text-xs font-semibold text-muted-foreground">{isLoading?'Looking around…':`${filtered.length} ${filtered.length===1?'student':'students'} to meet`}</p><p className="hidden items-center gap-1 text-[11px] text-muted-foreground sm:flex"><LockKeyhole size={12}/> Only verified campus profiles</p></div>
    {start.isError&&<p className="mb-4 rounded-xl bg-[#f8e9e7] p-3 text-xs text-[#a5413e]" role="alert">Couldn’t open a conversation just now. Please try again.</p>}
    {isLoading?<LoadingRows/>:isError?<ErrorNotice retry={()=>void refetch()}/>:filtered.length?<div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{filtered.map((person,index)=><article key={person.id} className={`animate-rise rounded-[22px] border border-[#e5e1d8] bg-[#fffdf8] p-5 shadow-[0_3px_12px_rgba(35,50,42,.025)] transition duration-200 hover:-translate-y-1 hover:shadow-[0_12px_32px_rgba(35,50,42,.08)] ${index%3===1?'delay-1':''}`} data-testid={`card-person-${person.id}`}><div className="flex items-start justify-between"><PersonAvatar person={person} size="lg"/>{person.isOnline?<span className="inline-flex items-center gap-1.5 text-[10px] font-bold text-primary"><span className="h-1.5 w-1.5 rounded-full bg-[#58a97c]"/>Online</span>:<span className="text-[10px] text-muted-foreground">{person.year?`${person.year}${person.year===1?'st':person.year===2?'nd':person.year===3?'rd':'th'} year`:''}</span>}</div><h2 className="mt-4 flex items-center gap-1.5 font-serif text-lg font-extrabold tracking-tight">{person.displayName}{person.verificationStatus==='verified'&&<BadgeCheck size={15} className="text-primary"/>}</h2><p className="mt-1 truncate text-xs font-semibold text-[#60736b]">{person.program||'Student'}{person.year?` · Year ${person.year}`:''}</p>{person.bio?<p className="mt-3 line-clamp-2 min-h-[40px] text-xs leading-5 text-muted-foreground">{person.bio}</p>:<p className="mt-3 min-h-[40px] text-xs leading-5 text-muted-foreground">{person.university||'Your campus'} community member</p>}<div className="mt-4 flex items-center justify-between border-t border-[#f0ede5] pt-4"><span className="truncate text-[10px] text-muted-foreground">{person.university||'Your university'}</span><Button size="sm" onClick={()=>startChat(person)} disabled={start.isPending} data-testid={`button-message-${person.id}`}>{start.isPending?'Opening…':<><MessageCircle size={14} className="mr-1.5"/>Message</>}</Button></div></article>)}</div>:<div className="rounded-[26px] border border-dashed border-[#d7d9ce] bg-[#fbfaf6] px-6 py-14 text-center"><span className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-[#eaf1eb] text-primary"><Users size={24}/></span><h2 className="mt-4 font-serif text-xl font-extrabold">No one found in this corner.</h2><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-muted-foreground">Try another name or program. Your next good conversation may be hiding behind a different search.</p><button onClick={()=>{setSearch('');setTab('all');}} className="mt-4 text-xs font-bold text-primary" data-testid="button-clear-people-search">Clear search</button></div>}
  </div>;
}

const verificationSchema=z.object({university:z.string().min(2,'Enter your university.'),campusEmail:z.string().email('Enter a valid campus email address.'),studentId:z.string().min(3,'Enter at least 3 characters.').max(64,'ID must be 64 characters or less.')});
function VerificationPage() {
  const {data:request,isLoading,isError,refetch}=useGetVerification();const submit=useSubmitVerification();const {data:me}=useGetMe();const refresh=useRefreshProductQueries();
  const form=useForm<z.infer<typeof verificationSchema>>({resolver:zodResolver(verificationSchema),defaultValues:{university:me?.university||'',campusEmail:'',studentId:''}});
  useEffect(()=>{if(me?.university)form.setValue('university',me.university);},[me?.university,form]);
  function onSubmit(values:z.infer<typeof verificationSchema>){submit.mutate({data:values},{onSuccess:()=>{form.reset({university:values.university,campusEmail:values.campusEmail,studentId:''});void refresh();}});}
  return <div className="animate-rise max-w-[1040px]"><PageTitle eyebrow="A trusted campus" title="Verify your student status." desc="A quick review keeps First Commit a place for real campus connections. Your full student ID is never shown on your profile."/>
    {isLoading?<LoadingRows/>:isError?<ErrorNotice retry={()=>void refetch()}/>:request&&request.status!=='rejected'?<div className="grid gap-6 lg:grid-cols-[1fr_300px]"><section className="rounded-[26px] border border-[#e4e0d7] bg-[#fffdf8] p-6 sm:p-9"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">Submission status</p><h2 className="mt-2 font-serif text-2xl font-extrabold">{request.status==='verified'?'You’re verified.':'Your request is in good hands.'}</h2></div><StatusPill status={request.status}/></div><p className="mt-4 max-w-xl text-sm leading-6 text-muted-foreground">{request.status==='verified'?'Your campus profile is confirmed. You can now connect with verified students.':`Submitted ${new Date(request.submittedAt).toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})}. We’ll let you know when the review is complete.`}</p><div className="mt-7 grid gap-3 sm:grid-cols-2"><div className="rounded-2xl bg-[#f5f3ec] p-4"><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">University</p><p className="mt-2 text-sm font-bold">{request.university}</p></div><div className="rounded-2xl bg-[#f5f3ec] p-4"><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Campus email</p><p className="mt-2 text-sm font-bold">{request.campusEmail}</p></div><div className="rounded-2xl bg-[#f5f3ec] p-4"><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Student ID</p><p className="mt-2 text-sm font-bold">Ending in {request.studentIdLastFour}</p></div><div className="rounded-2xl bg-[#f5f3ec] p-4"><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Applicant</p><p className="mt-2 text-sm font-bold">{request.applicantName}</p></div></div></section><aside className="rounded-[26px] bg-[#e9f0e8] p-6"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-white text-primary"><ShieldCheck size={21}/></span><h3 className="mt-4 font-serif text-lg font-extrabold">Your details stay yours.</h3><p className="mt-2 text-xs leading-6 text-[#5c7064]">Student details are used only to confirm campus membership. Your full ID is kept private, and only the last four digits are visible to reviewers.</p><div className="mt-5 flex items-center gap-2 text-xs font-bold text-primary"><LockKeyhole size={14}/>Private by design</div></aside></div>:<div className="grid gap-6 lg:grid-cols-[1fr_300px]"><section id="verification-resubmit" className="rounded-[26px] border border-[#e4e0d7] bg-[#fffdf8] p-6 sm:p-9">{request?.status==='rejected'&&<div className="mb-6 flex items-start gap-3 rounded-2xl border border-[#ebd4c9] bg-[#fff6f0] p-4 text-sm text-[#8a5140]" data-testid="status-verification-rejected"><StatusPill status="rejected"/><div><p className="font-bold">A little more information is needed.</p><p className="mt-1 leading-5">{request.reviewNote||'Your request was not approved. Review your information and submit updated details.'}</p></div></div>}<div className="mb-7 flex items-start gap-4"><span className="grid h-12 w-12 shrink-0 place-items-center rounded-2xl bg-[#e8f0e8] text-primary"><GraduationCap size={23}/></span><div><h2 className="font-serif text-2xl font-extrabold tracking-tight">{request?.status==='rejected'?'Update your details.':'Show us you’re part of campus.'}</h2><p className="mt-1 text-sm leading-6 text-muted-foreground">Share a few details. Our campus team will review your request.</p></div></div><Form {...form}><form onSubmit={form.handleSubmit(onSubmit)} className="space-y-5">{[
      {name:'university' as const,label:'University or college',placeholder:'e.g. Northbridge University'},
      {name:'campusEmail' as const,label:'Campus email address',placeholder:'you@university.edu'},
      {name:'studentId' as const,label:'Student ID number',placeholder:'Enter your full student ID'},
    ].map(item=><FormField key={item.name} control={form.control} name={item.name} render={({field})=><FormItem><FormLabel className="text-xs font-bold">{item.label}</FormLabel><FormControl><Input {...field} type={item.name==='campusEmail'?'email':'text'} placeholder={item.placeholder} className="h-11 rounded-xl bg-[#fbfaf6]" data-testid={`input-verification-${item.name}`}/></FormControl><FormMessage/></FormItem>}/>)}<div className="rounded-xl bg-[#f5f3ec] p-3.5 text-xs leading-5 text-muted-foreground"><LockKeyhole size={14} className="mr-1.5 inline text-primary"/>Your ID number is kept private. We show only its last four digits to reviewers.</div><Button type="submit" disabled={submit.isPending} className="h-11 w-full rounded-xl" data-testid="button-submit-verification">{submit.isPending?'Submitting request…':'Submit for review'} <ArrowRight size={15} className="ml-2"/></Button></form></Form></section><aside className="rounded-[26px] bg-[#223a38] p-6 text-[#f7f4ea]"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-[#31564b] text-[#b8d7bd]"><ShieldCheck size={21}/></span><h3 className="mt-4 font-serif text-lg font-extrabold">Why verify?</h3><p className="mt-2 text-xs leading-6 text-[#c4d0c7]">It helps ensure conversations start between people who actually share a campus. It’s the small thing that makes the commons feel trustworthy.</p><div className="mt-5 space-y-3 text-xs"><p className="flex gap-2"><Check size={14} className="shrink-0 text-[#acd0b2]"/> Access campus people</p><p className="flex gap-2"><Check size={14} className="shrink-0 text-[#acd0b2]"/> Keep your student ID private</p></div></aside></div>}
    {submit.isError&&<p className="mt-4 rounded-xl bg-[#f8e9e7] p-3 text-sm text-[#a5413e]" role="alert">We couldn’t submit your request. Check the details and try again.</p>}
  </div>;
}

const profileSchema=z.object({displayName:z.string().min(1).max(80),username:z.string().min(3).max(24).regex(/^[a-zA-Z0-9_]+$/,'Use letters, numbers, and underscores.'),university:z.string().min(2).max(120),program:z.string().min(2).max(100),year:z.coerce.number().min(1).max(8),bio:z.string().max(240)});
function SettingsPage() {
  const {data:me,isLoading,isError,refetch}=useGetMe();const update=useUpdateMe();const refresh=useRefreshProductQueries();
  const form=useForm<z.infer<typeof profileSchema>>({resolver:zodResolver(profileSchema),defaultValues:{displayName:'',username:'',university:'',program:'',year:1,bio:''}});
  const initialized=useRef<string|null>(null);
  useEffect(()=>{if(me&&initialized.current!==me.id){initialized.current=me.id;form.reset({displayName:me.displayName,username:me.username,university:me.university||'',program:me.program||'',year:me.year||1,bio:me.bio||''});}},[me,form]);
  function onSubmit(values:z.infer<typeof profileSchema>){update.mutate({data:values},{onSuccess:()=>{void refresh();}});}
  if(isLoading)return <LoadingRows/>;if(isError)return <ErrorNotice retry={()=>void refetch()}/>;
  return <div className="animate-rise max-w-[1000px]"><PageTitle eyebrow="Your place in the commons" title="Your profile." desc="Make it easy for classmates to recognize you and find a reason to say hello."/>
    <div className="grid gap-6 lg:grid-cols-[285px_1fr]"><aside className="h-fit rounded-[26px] border border-[#e4e0d7] bg-[#fffdf8] p-6"><div className="flex items-center gap-4"><PersonAvatar person={me} size="lg"/><div className="min-w-0"><p className="truncate font-serif text-lg font-extrabold">{me?.displayName}</p><p className="truncate text-xs text-muted-foreground">@{me?.username}</p></div></div>{me?.verificationStatus==='verified'?<div className="mt-5"><VerifiedMark/></div>:<div className="mt-5 flex items-center justify-between rounded-xl bg-[#f7efdc] p-3"><span className="text-xs font-semibold text-[#85662f]">Student not verified yet</span><Link href="/verification" className="text-xs font-bold text-primary" data-testid="link-profile-verification">Verify</Link></div>}<div className="mt-6 border-t border-[#eeeae2] pt-5"><p className="text-[10px] font-bold uppercase tracking-[.15em] text-muted-foreground">Your campus card</p><div className="mt-3 flex items-start gap-2 text-xs leading-5 text-muted-foreground"><GraduationCap size={14} className="mt-0.5 shrink-0 text-primary"/>{me?.university||'University not set'}</div><div className="mt-2 flex items-start gap-2 text-xs leading-5 text-muted-foreground"><BookOpen size={14} className="mt-0.5 shrink-0 text-primary"/>{me?.program||'Program not set'}{me?.year?` · Year ${me.year}`:''}</div></div></aside>
    <section className="rounded-[26px] border border-[#e4e0d7] bg-[#fffdf8] p-6 sm:p-8"><div className="mb-6"><h2 className="font-serif text-xl font-extrabold">A little about you</h2><p className="mt-1 text-xs text-muted-foreground">Only share what you’re comfortable sharing.</p></div><Form {...form}><form onSubmit={form.handleSubmit(onSubmit)} className="grid gap-x-5 gap-y-4 sm:grid-cols-2">{[
      {name:'displayName' as const,label:'Name',placeholder:'Your name'}, {name:'username' as const,label:'Username',placeholder:'your_handle'},
      {name:'university' as const,label:'University',placeholder:'Your campus'}, {name:'program' as const,label:'Program or major',placeholder:'What are you studying?'},
    ].map(item=><FormField key={item.name} control={form.control} name={item.name} render={({field})=><FormItem><FormLabel className="text-xs font-bold">{item.label}</FormLabel><FormControl><Input {...field} className="h-11 rounded-xl bg-[#fbfaf6]" placeholder={item.placeholder} data-testid={`input-profile-${item.name}`}/></FormControl><FormMessage/></FormItem>}/>)}<FormField control={form.control} name="year" render={({field})=><FormItem><FormLabel className="text-xs font-bold">Year of study</FormLabel><FormControl><Input type="number" min={1} max={8} {...field} className="h-11 rounded-xl bg-[#fbfaf6]" data-testid="input-profile-year"/></FormControl><FormMessage/></FormItem>}/><div className="hidden sm:block"/><FormField control={form.control} name="bio" render={({field})=><FormItem className="sm:col-span-2"><FormLabel className="text-xs font-bold">A sentence about you</FormLabel><FormControl><Textarea {...field} maxLength={240} rows={4} className="resize-none rounded-xl bg-[#fbfaf6]" placeholder="What are you curious about? What would you like to talk about?" data-testid="input-profile-bio"/></FormControl><div className="flex justify-between"><FormMessage/><span className="text-[10px] text-muted-foreground">{form.watch('bio')?.length||0}/240</span></div></FormItem>}/><div className="mt-2 flex flex-col-reverse justify-between gap-3 border-t border-[#eeeae2] pt-5 sm:col-span-2 sm:flex-row sm:items-center"><p className="text-[11px] text-muted-foreground">Email: {me?.email||'Managed through your sign-in account'}</p><Button type="submit" disabled={update.isPending} className="rounded-xl" data-testid="button-save-profile">{update.isPending?'Saving…':'Save changes'} <Check size={15} className="ml-2"/></Button></div></form></Form>{update.isSuccess&&<p className="mt-3 text-right text-xs font-semibold text-primary">Profile saved.</p>}{update.isError&&<p className="mt-3 text-right text-xs text-destructive">We couldn’t save that change. Try again.</p>}</section></div>
  </div>;
}

function AdminVerificationPage() {
  const {data:requests,isLoading,isError,refetch}=useListVerificationRequests();const review=useReviewVerification();const refresh=useRefreshProductQueries();const [noteId,setNoteId]=useState<string|null>(null);const [note,setNote]=useState('');
  return <div className="animate-rise"><PageTitle eyebrow="Campus trust team" title="Verification review." desc="Review student submissions and help keep the commons grounded in real campus life." action={<span className="inline-flex items-center gap-2 rounded-full bg-[#e9f1e9] px-3.5 py-2 text-xs font-bold text-primary"><ShieldCheck size={14}/> Reviewer workspace</span>}/>
    <div className="mb-5 flex items-center justify-between rounded-2xl bg-[#223a38] p-5 text-[#f8f4ea] sm:p-6"><div><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#b8d7bd]">Queue overview</p><p className="mt-2 font-serif text-2xl font-extrabold">{requests?.length??0} awaiting review</p></div><span className="grid h-12 w-12 place-items-center rounded-2xl bg-[#31564b] text-[#b8d7bd]"><Inbox size={22}/></span></div>
    {isLoading?<LoadingRows/>:isError?<ErrorNotice retry={()=>void refetch()}/>:requests?.length?<div className="space-y-3">{requests.map((request,index)=><VerificationReviewCard key={request.id} request={request} number={index+1} pending={review.isPending} note={noteId===request.id?note:''} noteOpen={noteId===request.id} setNote={(v)=>{setNoteId(request.id);setNote(v);}} onReview={(status)=>review.mutate({verificationId:request.id,data:{status,reviewNote:noteId===request.id?note:undefined}},{onSuccess:()=>{setNoteId(null);setNote('');void refresh();}})}/>)}</div>:<div className="rounded-[26px] border border-dashed border-[#d7d9ce] bg-[#fbfaf6] px-6 py-16 text-center"><span className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-[#eaf1eb] text-primary"><CheckCheck size={24}/></span><h2 className="mt-4 font-serif text-xl font-extrabold">The queue is clear.</h2><p className="mt-2 text-sm text-muted-foreground">New student submissions will show up here.</p></div>}
  </div>;
}
function VerificationReviewCard({request,number,pending,note,noteOpen,setNote,onReview}:{request:Verification;number:number;pending:boolean;note:string;noteOpen:boolean;setNote:(v:string)=>void;onReview:(status:'verified'|'rejected')=>void}) {
  return <article className="rounded-[24px] border border-[#e5e1d8] bg-[#fffdf8] p-5 sm:p-6" data-testid={`verification-request-${request.id}`}><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div className="flex gap-4"><span className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-[#eaf1eb] font-serif text-lg font-extrabold text-primary">{String(number).padStart(2,'0')}</span><div><div className="flex flex-wrap items-center gap-2"><h2 className="font-serif text-lg font-extrabold">{request.applicantName}</h2><StatusPill status={request.status}/></div><p className="mt-1 text-xs text-muted-foreground">Submitted {new Date(request.submittedAt).toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})}</p></div></div><div className="flex flex-wrap gap-2"><Button variant="outline" size="sm" disabled={pending} onClick={()=>onReview('rejected')} className="border-[#e9d6d0] text-[#a5413e] hover:bg-[#fff3ef]" data-testid={`button-reject-${request.id}`}><X size={14} className="mr-1"/> Reject</Button><Button size="sm" disabled={pending} onClick={()=>onReview('verified')} data-testid={`button-approve-${request.id}`}><Check size={14} className="mr-1"/> Approve</Button></div></div><div className="mt-5 grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-[#f6f4ed] p-3"><p className="text-[9px] font-bold uppercase tracking-wider text-muted-foreground">Campus</p><p className="mt-1.5 text-xs font-bold">{request.university}</p></div><div className="rounded-xl bg-[#f6f4ed] p-3"><p className="text-[9px] font-bold uppercase tracking-wider text-muted-foreground">Campus email</p><p className="mt-1.5 break-all text-xs font-bold">{request.campusEmail}</p></div><div className="rounded-xl bg-[#f6f4ed] p-3"><p className="text-[9px] font-bold uppercase tracking-wider text-muted-foreground">Student ID</p><p className="mt-1.5 text-xs font-bold">•••• {request.studentIdLastFour}</p></div></div><button onClick={()=>setNote('')} className="mt-4 text-[11px] font-bold text-primary" data-testid={`button-review-note-${request.id}`}>{noteOpen?'Reviewer note':'Add reviewer note'}</button>{noteOpen&&<div className="mt-3"><Textarea value={note} maxLength={300} onChange={e=>setNote(e.target.value)} rows={2} placeholder="Add a note for the student (optional)" className="rounded-xl bg-[#fbfaf6] text-xs" data-testid={`input-review-note-${request.id}`}/><p className="mt-1 text-right text-[10px] text-muted-foreground">{note.length}/300</p></div>}</article>;
}

function Router() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Switch>
    <Route path="/" component={Landing}/>
    <Route path="/sign-in/*?" component={SignInPage}/>
    <Route path="/sign-up/*?" component={SignUpPage}/>
    <Route path="/app">{()=> <ProtectedShell><ChatHub/></ProtectedShell>}</Route>
    <Route path="/people">{()=> <ProtectedShell><PeoplePage/></ProtectedShell>}</Route>
    <Route path="/verification">{()=> <ProtectedShell><VerificationPage/></ProtectedShell>}</Route>
    <Route path="/settings">{()=> <ProtectedShell><SettingsPage/></ProtectedShell>}</Route>
    <Route path="/admin/verifications">{()=> <AdminRoute/>}</Route>
    <Route component={NotFound}/>
  </Switch></ErrorBoundary>;
}
function AdminRoute() { const {user}=useUser();return user?.publicMetadata?.role==='admin'?<ProtectedShell><AdminVerificationPage/></ProtectedShell>:<ProtectedShell><div className="mx-auto max-w-xl rounded-[26px] border border-[#e4e0d7] bg-[#fffdf8] p-10 text-center"><span className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-[#f7efdc] text-[#8a682a]"><LockKeyhole size={23}/></span><h1 className="mt-5 font-serif text-2xl font-extrabold">Reviewer access only.</h1><p className="mt-2 text-sm text-muted-foreground">This review desk is reserved for the campus trust team.</p><Link href="/app" className="mt-5 inline-block text-sm font-bold text-primary" data-testid="link-admin-back">Back to messages</Link></div></ProtectedShell>;}
function ClerkRoutes() {
  const [,setLocation]=useLocation();
  return <ClerkProvider publishableKey={clerkPubKey} proxyUrl={clerkProxyUrl} appearance={clerkAppearance} signInUrl={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} localization={{signIn:{start:{title:'Welcome back',subtitle:'Pick up where campus left off.'}},signUp:{start:{title:'Your campus starts here',subtitle:'Create your First Commit account.'}}}} routerPush={(to: string)=>setLocation(stripBase(to))} routerReplace={(to: string)=>setLocation(stripBase(to),{replace:true})}>
    <QueryClientProvider client={queryClient}><TooltipProvider><ClerkQueryCacheInvalidator/><Router/><Toaster/></TooltipProvider></QueryClientProvider>
  </ClerkProvider>;
}
function App() { return <WouterRouter base={basePath}><ClerkRoutes/></WouterRouter>; }
export default App;
